contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test: attempt to withdraw `amount` from c.
    // Make function payable so prover can supply Ether if desired (not used here).
    function run(uint amount) public payable {
        require(amount <= 1 ether);

        // observe balance before the call
        uint beforeBal = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // attempt withdraw(amount) and record whether it reverted
        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe balance after the call
        uint afterBal = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        // General rule: withdraw either reverts leaving balance and depositsCount unchanged,
        // or succeeds and decreases balance by exactly amount and depositsCount unchanged.
        assert(reverted ? (afterBal == beforeBal && afterDeposits == beforeDeposits)
                         : (beforeBal >= amount && afterBal == beforeBal - amount && afterDeposits == beforeDeposits));
    }

    // Allow receiving ETH when C sends funds here
    receive() external payable {}
}

